  TransactionsFts createAlias(String alias) {
    return TransactionsFts(attachedDatabase, alias);
  }

  @override
  bool get dontWriteConstraints => true;
  @override
  String get moduleAndArgs =>
      'fts5(note, content = transactions, content_rowid = rowid)';
